# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students for contact sheet")
    for item in students:
        if not item.email:
            raise ProjectError(
                f"no email for {item.display_name}"
            )


def _width(values: Iterable[str]) -> int:
    return max(len(value) for value in values)


def contact_rows(students: Iterable[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    ordered = sorted(
        students, key=lambda item: item.display_name
    )
    _check(ordered)
    name_w = _width(item.display_name for item in ordered)
    sect_w = _width(item.section for item in ordered)
    return [
        f"{item.display_name:<{name_w}}  "
        f"{item.section:<{sect_w}}  {item.email}"
        for item in ordered
    ]

