# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


def _student(last, first, email="a@x.org"):
    return Student("id", last, first, "A1", email)


class ContactRowsTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows(
            [
                _student("Young", "Al", "y@x.org"),
                _student("Abbott", "Bea", "b@x.org"),
            ]
        )
        self.assertEqual(
            rows,
            [
                "Abbott, Bea  A1  b@x.org",
                "Young, Al    A1  y@x.org",
            ],
        )

    def test_missing_email_names_student(self):
        with self.assertRaises(ProjectError) as caught:
            contact_rows([_student("Lee", "Kim", None)])
        self.assertIn("Lee, Kim", str(caught.exception))

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
